fn write_test_filter_pack(path: &std::path::Path, pack_id: &str, pattern: &str, replacement: &str) {
    let toml_str = format!(
        r#"
schema_version = "1.0"

[pack]
id = "{pack_id}"
version = "1.0.0"

[[filters]]
id = "git-version-marker"
version = "1.0.0"
match_command = ["git", "--version"]

[[filters.stages]]
type = "replace"
pattern = "{pattern}"
replacement = "{replacement}"
"#
    );
    std::fs::write(path, toml_str).unwrap();
}

